class Solution {
    vector<int> parent, sz;

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);

        if (a == b)
            return;

        if (sz[a] < sz[b])
            swap(a, b);

        parent[b] = a;
        sz[a] += sz[b];
    }

    bool inside(long long px, long long py,
                long long x, long long y,
                long long r) {
        long long dx = px - x;
        long long dy = py - y;

        return dx * dx + dy * dy <= r * r;
    }

    bool connected(vector<int>& a,
                   vector<int>& b,
                   long long X, long long Y) {
        long long x1 = a[0], y1 = a[1], r1 = a[2];
        long long x2 = b[0], y2 = b[1], r2 = b[2];

        long long dx = x1 - x2;
        long long dy = y1 - y2;
        long long r = r1 + r2;

        // Circles must intersect or touch.
        if (dx * dx + dy * dy > r * r)
            return false;

        // Their intersection must reach
        // the rectangle's interior.
        // Use 64-bit arithmetic to avoid overflow.
        return x1 * r2 + x2 * r1 < r * X &&
               y1 * r2 + y2 * r1 < r * Y;
    }

public:
    bool canReachCorner(int xCorner, int yCorner,
                        vector<vector<int>>& circles) {
        int n = circles.size();

        long long X = xCorner;
        long long Y = yCorner;

        // Two virtual nodes:
        // n     = left or top boundary
        // n + 1 = right or bottom boundary
        parent.resize(n + 2);
        sz.assign(n + 2, 1);

        for (int i = 0; i < n + 2; ++i)
            parent[i] = i;

        for (int i = 0; i < n; ++i) {
            long long x = circles[i][0];
            long long y = circles[i][1];
            long long r = circles[i][2];

            // Start or destination lies in a circle.
            if (inside(0, 0, x, y, r) ||
                inside(X, Y, x, y, r))
                return false;

            // Circle touches left boundary.
            bool left = (x - r <= 0 && y <= Y);

            // Circle touches top boundary.
            bool top = (y + r >= Y && x <= X);

            // Circle touches right boundary.
            bool right = (x + r >= X && y <= Y);

            // Circle touches bottom boundary.
            bool bottom = (y - r <= 0 && x <= X);

            if (left || top)
                unite(i, n);

            if (right || bottom)
                unite(i, n + 1);

            // Connect intersecting circles.
            for (int j = 0; j < i; ++j) {
                if (connected(circles[i], circles[j],
                              X, Y)) {
                    unite(i, j);
                }
            }

            // Barrier detected.
            if (find(n) == find(n + 1))
                return false;
        }

        return find(n) != find(n + 1);
    }
};
